.embedded-video-v26 {
    position: relative;
    padding-top: $measure--small1;
    padding-bottom: $measure--small1;
    display: flex;
    flex-direction: column;

    &.embedded-video-v26--deco {
        padding-right: $measure--small1;
    }

    .embedded-video-v26__triangles {
        position: absolute;
        top: 0;
        right: 0;
        width: $measure--huge3;
        height: $measure--huge3;
    }

    .cover-image__container {
        position: relative;

        &:hover {
            .cover-image__veil .cover-image__button {
                background: $color-purewhite;
                outline-color: $color-purewhite;

                &:before {
                    color: $color-nearblack;
                }
            }
        }
    }

    .cover-image {
        border-radius: $measure--half;
        width: 100%;
    }

    .cover-image__veil,
    .cover-image__veil--cookie {
        &:before {
            position: absolute;
            width: 100%;
            height: 100%;
            content: '';
            z-index: z-index('above');
            border-radius: $measure--half;
            top: 0;
            left: 0;
        }
    }

    .cover-image__veil:before {
        background: linear-gradient(0deg, rgba(0, 0, 0, 0.8) 10%, transparent);
    }

    .cover-image__content {
        position: absolute;
        bottom: $measure--small4;
        left: $measure--small4;
        display: flex;
        flex-direction: row;
        color: $color-purewhite;
        z-index: z-index('above');
    }

    .cover-image__veil:has(+ .cover-image__veil--cookie:not([data-cybot-cookiebot-blocked='true'])) {
        display: none !important;
    }

    .cover-image__veil--cookie {
        &:before {
            background: linear-gradient(0deg, rgba(0, 0, 0, 0.8));
        }

        .cover-image__content {
            @include media('<=mobile') {
                margin: auto;
                inset: 0;
                padding: $measure--half;

                .cover-image__button {
                    margin-left: $measure--half;
                }

                .cookieconsent-optout-marketing__inner__content {
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                }
            }

            .cover-image__button {
                opacity: 0.5;
            }

            .cookieconsent-optout-marketing__inner {
                display: flex;
                padding: 0 $measure--small1;
            }

            p {
                line-height: $measure--small1;

                &:first-of-type {
                    margin-top: 0;
                }
            }

            a {
                text-decoration: underline;
                color: $color-purewhite;
                display: inline;

                &:visited {
                    color: $color-purewhite;
                }

                &:focus {
                    outline-color: $color-purewhite;
                }
            }
        }
    }

    .cover-image__intro {
        margin-top: 0;
        align-self: center;
        @include epsilontype;
        @include font-family('heading');
        @include heading-font-features();
        padding: 0 $measure--small1;
        line-height: $measure--small3;
    }

    .cover-image__button {
        background-color: $color-red50;
        width: $measure--medium1;
        height: $measure--medium1;
        border-radius: 50%;
        display: flex;
        justify-content: center;
        align-items: center;
        outline-offset: $measure--half * 0.8;
        outline-style: $border-style-solid;
        outline-width: $border-width-default;
        outline-color: $color-red50;
        padding-left: $measure--quarter;
        flex-shrink: 0;
        align-self: center;

        &:before {
            color: $color-purewhite;
            @include deltatype;
        }
    }

    .cover-image__content:has(:focus-visible) {
        outline-color: $color-purewhite;
        outline-offset: $border-width-thick;
        outline-style: $border-style-solid;
        outline-width: $border-width-default;
    }

    .youtube-video__wrapper {
        height: 0;
        padding-bottom: 56.25%;
        position: relative;
        width: 100%;
        cursor: pointer;

        iframe {
            height: 100%;
            left: 0;
            margin: 0;
            position: absolute;
            top: 0;
            width: 100%;
            border: none;
            border-radius: $measure--half;
        }
    }

    .youtube-video__caption-element--text,
    .youtube-video__caption-element--time {
        display: block;
    }

    .youtube-video__caption-element--time span {
        font-weight: $font-weight-normal;
    }
}

.embedded-video-v26[data-video-loaded='false'] {
    .youtube-video__wrapper {
        height: initial;
        padding-bottom: initial;
    }
}

// transscript accordion styles
.js .embedded-video-v26 .accordion-v26 {
    .accordion__heading {
        border-radius: $measure--half;
        border: $border-width-hairline $border-style-solid $color-nearblack;

        &[data-open='true'] {
            border-radius: $measure--half $measure--half 0 0;
            border: none;

            button {
                border-radius: $measure--half $measure--half 0 0;
                border-bottom: none;

                &:focus {
                    border-bottom: none;
                }
            }

            + .accordion__body {
                border-radius: 0 0 $measure--half $measure--half;
            }
        }

        &[data-open='false'] {
            button {
                &:focus,
                &:active,
                &:hover {
                    border-radius: $measure--half;
                }

                div {
                    border-bottom: none;
                }
            }
        }
    }

    .accordion__heading__text {
        @include extrasmalltype;
    }
}
